145	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
146	
147	const followUpDiscountOf = (
148	  basePremium: number,
149	  previousQuoteCount: number,
150	): number =>
151	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
152	
153	const exactPremiumBeforeFeeOf = (
154	  items: readonly Item[],
155	  customer: Customer,
156	  previousQuoteCount: number,
157	): number => {
158	  const basePremium = policyBasePremiumOf(items);
