361	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
362	
363	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
364	  steps.filter(isQuoteStep);
365	
366	const quoteStepsBefore = (
367	  steps: readonly Step[],
368	  stepIndex: number,
