371	// The state a scenario carries from one step to the next: the results produced
372	// so far, and how much of each policy's cap is still available.
373	interface ScenarioState {
374	  readonly results: readonly StepResult[];
375	  readonly remainingCaps: readonly number[];
376	}
377	
378	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
