388	  remainingCaps.map((cap, index) => (index === policy ? remainingCap : cap));
389	
390	const stateAfterQuote = (
391	  state: ScenarioState,
392	  result: QuoteResult,
393	): ScenarioState => ({ ...state, results: [...state.results, result] });
394	
395	const stateAfterClaim = (
396	  state: ScenarioState,
397	  step: ClaimStep,
398	  result: ClaimResult,
399	): ScenarioState => ({
400	  results: [...state.results, result],
401	  remainingCaps: capsAfterClaim(
402	    state.remainingCaps,
403	    step.policy,
404	    result.remainingCap,
