420	            ),
421	          )
422	        : stateAfterClaim(
423	            state,
424	            step,
425	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
426	          ),
427	    initialStateOf(policies),
428	  );
429	
430	  return { results };
431	};
